<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body, html {
            height: 100%;
            margin: 0;
        }
        .iframe-container {
            position: relative;
            height: 100vh; /* Set height to 95% of the viewport height */
            overflow: hidden; /* Hide overflow */
        }
        .iframe-container iframe {
            position: absolute;
            top: -4.5%; /* Move the iframe up by 5% */
            left: 0;
            width: 100%;
            height: 100%; /* Increase height to cover the hidden area */
            border: none;
        }
        .iframe-container menu-btn-group {
            visibility: hidden;
        }
    </style>
</head>
<body>
    <div class="iframe-container">
        <iframe id="sales-invoice-frame" src="http://89.58.7.82:8080/app/sales-invoice"></iframe>
    </div>
    <script>
        document.getElementById('sales-invoice-frame').onload = function() {
            try {
                let iframeDoc = document.getElementById('sales-invoice-frame').contentWindow.document;

                // Hide the navbar by class name
                let navbar = iframeDoc.querySelector('.navbar');
                if (navbar) {
                    navbar.style.display = 'none';
                }

                setTimeout(function() {
                    // Check if the element exists before modifying it
                    let btnGroup = iframeDoc.querySelector('.custom-btn-group');
                    if (btnGroup) {
                        btnGroup.style.visibility = 'hidden';
                    } else {
                        console.log("Element .custom-btn-group not found.");
                    }
                }, 500); // Delay to ensure content is fully loaded
            } catch (e) {
                console.error("Error accessing iframe content: ", e);
            }
        };
    </script>
</body>
</html>
